import sys

def solve():
    try:
        input_str = sys.stdin.read().strip()
        if not input_str:
            return
        X = int(input_str)
    except ValueError:
        return

    n = 1
    fact = 1
    while fact < X:
        n += 1
        fact *= n

    print(n)

if __name__ == '__main__':
    solve()
